#include <stdio.h>
#include <string.h>
#include <ctype.h>

/*
 * Simple Soundex implementation matching the behaviour of the original
 * obfuscated binary "prog27_soundex".
 *
 * The program expects a single command‑line argument. If no argument is
 * supplied, or the argument is an empty string, it prints "EMPTY".
 * Otherwise it prints a four‑character Soundex code consisting of the
 * first letter (uppercase) followed by three digits (0‑6). Digits are
 * derived from the remaining letters using the classic Soundex mapping:
 *   B, F, P, V           -> 1
 *   C, G, J, K, Q, S, X, Z -> 2
 *   D, T                 -> 3
 *   L                    -> 4
 *   M, N                 -> 5
 *   R                    -> 6
 *   A, E, I, O, U, H, W, Y -> 0 (ignored)
 * Consecutive duplicate digits are collapsed, and zeros are not added
 * to the output. The result is padded with '0' characters to a total of
 * four characters.
 */

static int soundex_digit(char c)
{
    switch (c) {
        case 'B': case 'F': case 'P': case 'V': return 1;
        case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z': return 2;
        case 'D': case 'T': return 3;
        case 'L': return 4;
        case 'M': case 'N': return 5;
        case 'R': return 6;
        default: return 0; // A, E, I, O, U, H, W, Y and any other character
    }
}

int main(int argc, char *argv[])
{
    if (argc < 2 || argv[1][0] == '\0') {
        puts("EMPTY");
        return 0;
    }

    const char *input = argv[1];
    char code[4];
    // first character, upper‑cased
    code[0] = (char)toupper((unsigned char)input[0]);
    int count = 0; // number of digits added
    int prev_digit = soundex_digit(code[0]); // first letter's digit for duplicate checking

    for (size_t i = 1; input[i] != '\0' && count < 3; ++i) {
        char ch = (char)toupper((unsigned char)input[i]);
        int digit = soundex_digit(ch);
        if (digit == 0) {
            // vowels and ignored letters reset duplicate checking
            prev_digit = 0;
            continue;
        }
        if (digit == prev_digit) {
            // skip duplicate digit
            continue;
        }
        code[1 + count] = (char)('0' + digit);
        ++count;
        prev_digit = digit;
    }
    // pad remaining positions with '0'
    while (count < 3) {
        code[1 + count] = '0';
        ++count;
    }
    // null‑terminate for puts
    code[3] = '\0';
    puts(code);
    return 0;
}
